// Shared page layout for the ratatoskr views (generated by refresh-plan/build_site.py; do not edit the copy in assets/).
// Order: throughput per workload -> latency percentiles per workload -> candidate/baseline heatmap -> results table
// -> one compact Setup table. Everything comes from the view's data file; SPEC (per view, in the page) only names fields.
//   SPEC = {x: cell field swept on the x axis, xTitle, group: cell -> [key, title, section, sortKey],
//           yTitle (throughput axis), cols (results table columns)}
const PAGE_BUILDS = [["unstable", "unstable", "--u"], ["frontier", "superset-frontier", "--f"]];
const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const fmtOps = v => v == null ? "—" : v >= 1e6 ? (v / 1e6).toFixed(v >= 1e7 ? 1 : 2) + "M" : v >= 1e3 ? (v / 1e3).toFixed(0) + "k" : String(Math.round(v));
const shade = (hex, a) => { const h = hex.replace("#", ""); const n = parseInt(h.length === 3 ? h.replace(/./g, "$&$&") : h, 16);
  return `rgba(${n >> 16 & 255},${n >> 8 & 255},${n & 255},${a})`; };
const escH = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const pageCharts = [];

const whiskers = { id: "whiskers", afterDatasetsDraw(chart) {   // min-max of valid reps
  const { ctx, scales: { y } } = chart;
  chart.data.datasets.forEach((ds, i) => {
    const meta = chart.getDatasetMeta(i); if (meta.hidden) return;
    ctx.save(); ctx.strokeStyle = ds.borderColor; ctx.lineWidth = 1.5;
    ds.data.forEach((p, j) => {
      if (!p || p.lo == null || p.hi == null || !meta.data[j]) return;
      const x = meta.data[j].x, a = y.getPixelForValue(p.lo), b = y.getPixelForValue(p.hi);
      ctx.beginPath(); ctx.moveTo(x, a); ctx.lineTo(x, b); ctx.moveTo(x - 5, a); ctx.lineTo(x + 5, a); ctx.moveTo(x - 5, b); ctx.lineTo(x + 5, b); ctx.stroke();
    });
    ctx.restore();
  });
}};
const notMeasured = { id: "notMeasured", afterDatasetsDraw(chart) {   // label a percentile that was not recorded
  const { ctx, chartArea } = chart;
  chart.data.datasets.forEach((ds, i) => {
    const meta = chart.getDatasetMeta(i);
    ds.data.forEach((v, j) => {
      if (v != null) return;
      const el = meta.data[j]; if (!el || !isFinite(el.x)) return;
      ctx.save(); ctx.translate(el.x, chartArea.bottom - 4); ctx.rotate(-Math.PI / 2);
      ctx.fillStyle = css("--muted"); ctx.font = "10px system-ui"; ctx.fillText(ds.gapLabel || "not measured", 0, 3); ctx.restore();
    });
  });
}};

// Charts are sized once per draw (responsive: false) and redrawn when the window width changes.
function pagePanel(host, title) {
  const d = document.createElement("div"); d.className = "panel";
  d.innerHTML = `<h3>${escH(title)}</h3><div style="position:relative;height:240px"><canvas></canvas></div>`;
  host.appendChild(d);
  const box = d.lastElementChild, cv = box.querySelector("canvas");
  const w = Math.max(200, Math.floor(box.getBoundingClientRect().width));
  cv.style.width = w + "px"; cv.style.height = "240px"; cv.width = w; cv.height = 240;
  return cv;
}
const pageChart = (host, title, config) => pageCharts.push(new Chart(pagePanel(host, title), config()));
function pageAxes() {
  return { responsive: false, maintainAspectRatio: false, animation: false, plugins: { legend: { display: false } },
    scales: { x: { grid: { color: css("--border") }, ticks: { color: css("--muted") } },
              y: { grid: { color: css("--border") }, ticks: { color: css("--muted") }, beginAtZero: true } } };
}
function pageGroups(D, S) {   // [{key, title, section, cells (sorted by x)}], ordered by sortKey then first appearance
  const m = new Map();
  D.cells.forEach((c, i) => { const [key, title, section, sk] = S.group(c);
    if (!m.has(key)) m.set(key, { key, title, section, sk: sk ?? 0, i, cells: [] }); m.get(key).cells.push(c); });
  const gs = [...m.values()].sort((a, b) => (a.sk - b.sk) || (a.i - b.i));
  gs.forEach(g => g.cells.sort((a, b) => a[S.x] - b[S.x]));
  return gs;
}
function sectioned(host, groups, each) {   // a sub-heading whenever the group's section changes
  let sec = null, grid = null;
  for (const g of groups) {
    if (!grid || g.section !== sec) {
      sec = g.section;
      if (sec) { const h = document.createElement("h3"); h.className = "sec"; h.textContent = sec; host.appendChild(h); }
      grid = document.createElement("div"); grid.className = "grid"; host.appendChild(grid);
    }
    each(grid, g);
  }
}

function pageThroughput(D, S, groups) {
  sectioned(document.getElementById("tput"), groups, (host, g) => pageChart(host, g.title, () => {
    const o = pageAxes();
    o.scales.x.title = { display: true, text: S.xTitle, color: css("--muted") };
    o.scales.y.title = { display: true, text: S.yTitle, color: css("--muted") };
    o.scales.y.ticks.callback = v => fmtOps(v);
    o.plugins.tooltip = { callbacks: { label: t => { const p = t.raw;
      return `${t.dataset.label}: ${p.y == null ? "MISSING" : fmtOps(p.y)}` + (p.lo != null ? ` (${fmtOps(p.lo)}–${fmtOps(p.hi)})` : ""); } } };
    return { type: "line", plugins: [whiskers], options: o, data: {
      labels: g.cells.map(c => `${c[S.x]}`),
      datasets: PAGE_BUILDS.map(([k, label, col]) => ({ label, borderColor: css(col), backgroundColor: css(col), pointRadius: 3, borderWidth: 2, spanGaps: false,
        data: g.cells.map(c => { const miss = c.missing && c.missing.builds.includes(k);
          return { x: `${c[S.x]}`, y: miss ? null : c[k].ops, lo: !miss && c[k].range ? c[k].range[0] : null, hi: !miss && c[k].range ? c[k].range[1] : null }; }) })) } };
  }));
}

function pageLatency(D, S, groups) {
  const PCT = [["p50_ms", "p50", 1], ["p99_ms", "p99", 0.7], ["p999_ms", "p99.9", 0.45]];
  sectioned(document.getElementById("lat"), groups, (host, g) => pageChart(host, g.title, () => {
    const o = pageAxes();
    o.scales.x.title = { display: true, text: S.xTitle, color: css("--muted") };
    o.scales.y.title = { display: true, text: "ms", color: css("--muted") };
    o.plugins.tooltip = { callbacks: { label: t => `${t.dataset.label}: ${t.raw == null ? t.dataset.gapLabel || "not measured" : t.raw.toFixed(3) + " ms"}` } };
    const datasets = [];
    for (const [k, label, col] of PAGE_BUILDS) for (const [f, name, alpha] of PCT) {
      const base = css(col);
      datasets.push({ label: `${label} ${name}`, backgroundColor: shade(base, k === "unstable" ? alpha : alpha * 0.75),
        borderColor: base, borderWidth: k === "frontier" ? 1 : 0,
        gapLabel: "not measured",
        data: g.cells.map(c => (c.missing && c.missing.builds.includes(k)) ? null : (c[k][f] == null ? null : c[k][f])) });
    }
    return { type: "bar", plugins: [notMeasured], options: o, data: { labels: g.cells.map(c => `${c[S.x]}`), datasets } };
  }));
}

function pageHeat(D, S, groups) {
  const xs = [...new Set(D.cells.map(c => c[S.x]))].sort((a, b) => a - b);
  const rs = D.cells.filter(c => c.compare).map(c => Math.abs(Math.log2(c.compare.ratio)));
  const L = Math.max(1, Math.ceil(Math.max(0, ...rs)));   // log2 scale, centred on 1.0, reaching the largest ratio
  const col = r => { const t = Math.max(-1, Math.min(1, Math.log2(r) / L));
    return t >= 0 ? shade(css("--f"), 0.08 + 0.82 * t) : shade(css("--u"), 0.08 + 0.82 * -t); };
  document.getElementById("scalebar").style.background =
    `linear-gradient(90deg, ${shade(css("--u"), .9)}, ${shade(css("--u"), .08)} 50%, ${shade(css("--f"), .08)} 50%, ${shade(css("--f"), .9)})`;
  document.getElementById("scalelo").textContent = `1/${2 ** L}×`;
  document.getElementById("scalehi").textContent = `${2 ** L}×`;
  const notes = [];
  let h = `<thead><tr><th class=l>workload</th>${xs.map(x => `<th>${x}</th>`).join("")}</tr></thead><tbody>`;
  let sec = null;
  for (const g of groups) {
    if (g.section && g.section !== sec) { sec = g.section; h += `<tr class=hsec><th class=l colspan=${xs.length + 1}>${escH(sec)}</th></tr>`; }
    h += `<tr><th class=l>${escH(g.title)}</th>`;
    for (const x of xs) {
      const c = g.cells.find(c => c[S.x] === x);
      if (!c) { h += `<td class=absent title="not in this sweep">·</td>`; continue; }
      if (c.missing) { notes.push([notes.length + 1, g.title, x, c.missing.reason]);
        h += `<td class=miss title="${escH(c.missing.reason)}">MISSING<sup>${notes.length}</sup></td>`; continue; }
      if (!c.compare) { h += `<td class=absent title="no ratio: ${escH(S.noRatio || "no comparable value")}">n/a</td>`; continue; }
      const r = c.compare.ratio, t = Math.abs(Math.log2(r)) / L;
      h += `<td style="background:${col(r)};${t > 0.55 ? "color:#fff" : ""}" title="${escH(c.compare.verdict)}${c.compare.high_var ? ", high variance" : ""}">${r.toFixed(2)}×</td>`;
    }
    h += "</tr>";
  }
  document.getElementById("heat").innerHTML = h + "</tbody>";
  document.getElementById("heatnotes").innerHTML = notes.length ? "<ol class=notes>" + notes.map(([n, t, x, why]) =>
    `<li value=${n}><b>${escH(t)}</b>, ${escH(S.xTitle)} ${x}: ${escH(why)}</li>`).join("") + "</ol>" : "";
}

function pageSetup(D, S) {   // every row from the data file: builds, harness, setup block, and what the cells imply
  const B = D.shown_builds || ["unstable", "frontier"], rows = [];
  const label = { unstable: "unstable", frontier: "superset-frontier" };
  for (const k of B) { const b = D.builds[k];
    rows.push([label[k] || b.label, `<code>${escH(b.sha.slice(0, 7))}</code> ${escH(b.repo.replace(/^https:\/\/github.com\//, ""))} ${escH(b.branch)}, committed ${escH((b.committed || "").slice(0, 10))}` +
      (b.config && !/^defaults/.test(b.config) ? `<br><span class=muted>${escH(b.config)}</span>` : "")]); }
  if (D.harness) rows.push(["harness", `${escH(D.harness.offbench.replace(/([0-9a-f]{9})[0-9a-f]+/, "$1"))}; ${escH(D.harness.build)}`]);
  const s = D.setup || {}, skip = new Set(["launch", "caveat", "frontier_config", "scenarios_from", "order", "reps", "window_s", "run_s"]);
  const region = (s.launch || "").match(/\b[a-z]{2}-[a-z]+-\d[a-z]\b/);
  if (region) rows.push(["region / AZ", `${region[0]}, ${escH((s.launch.split(", ").slice(2).join(", ")) || "")}`]);
  if (S.steps) rows.push([S.steps.title, [...new Map(D.cells.map(c => [c[S.x], S.steps.row(c)])).entries()]
    .sort((a, b) => a[0] - b[0]).map(([, v]) => escH(v)).join("<br>")]);
  for (const [k, v] of Object.entries(s)) if (!skip.has(k) && typeof v !== "object")
    rows.push([k.replace(/_/g, " "), String(v).split(/;\s+/).map(escH).join("<br>")]);
  if (s.frontier_config) rows.push(["frontier config", escH(s.frontier_config)]);
  const conns = [...new Set(D.cells.filter(c => c.conns).map(c => `P${c.P}: ${c.conns.toLocaleString()}`))];
  if (conns.length) rows.push(["connections", conns.join(", ")]);
  rows.push(["run / window", [s.run_s ? `${s.run_s} s run` : null, s.window_s ? `${s.window_s} s measured window` : null].filter(Boolean).join(", ") || "—"]);
  const nreps = Math.max(0, ...D.cells.flatMap(c => B.map(k => c[k].reps.length)));
  rows.push(["reps", `${s.reps || nreps} per build` + (s.order ? `, ${escH(s.order)}` : "")]);
  const ts = D.cells.flatMap(c => B.flatMap(k => c[k].reps.map(r => r.ts))).filter(Boolean).sort();
  if (ts.length) rows.push(["measured", ts[0].slice(0, 10) === ts[ts.length - 1].slice(0, 10) ? ts[0].slice(0, 10) : `${ts[0].slice(0, 10)} – ${ts[ts.length - 1].slice(0, 10)}`]);
  if (s.caveat) rows.push(["note", escH(s.caveat)]);
  const method = (D.headline || "").split("Method: ")[1];
  if (method) rows.push(["method", escH(method.replace(/<[^>]+>/g, ""))]);
  if (s.scenarios_from) rows.push(["scenarios from", escH(s.scenarios_from)]);
  document.getElementById("setuptab").innerHTML = rows.map(([k, v]) => `<tr><th>${escH(k)}</th><td>${v}</td></tr>`).join("");
}

function renderPage(D, S) {
  render(D, S.cols);   // status, headline, results table (and the replica capacity table) from view.js
  pageSetup(D, S);
  const groups = pageGroups(D, S);
  const draw = () => {
    pageCharts.splice(0).forEach(c => c.destroy());
    ["tput", "lat"].forEach(id => document.getElementById(id).innerHTML = "");
    pageThroughput(D, S, groups); pageLatency(D, S, groups); pageHeat(D, S, groups);
  };
  draw();
  matchMedia("(prefers-color-scheme: dark)").addEventListener("change", draw);
  let lastW = innerWidth, t = null;
  addEventListener("resize", () => { if (innerWidth === lastW) return; lastW = innerWidth; clearTimeout(t); t = setTimeout(draw, 200); });
}
